/bin/bash -c "python3 - <<'PY'
# Check Algorithm 1's role assignment on an example permitted by the CMP schema.
gold={(1,'Arg1','A'),(1,'Arg2','B'),(2,'Arg1','B'),(2,'Arg2','A')}
links={(trigger,span) for trigger,role,span in gold}
args={(span,role) for trigger,role,span in gold}
decoded={(trigger,role,span) for span,role in args for trigger in [1,2] if (trigger,span) in links}
alternate={(1,'Arg1','B'),(1,'Arg2','A'),(2,'Arg1','A'),(2,'Arg2','B')}
print('Same EAL links for opposite event-role assignments:', links=={(t,s) for t,r,s in alternate})
print('Same THL role labels for opposite event-role assignments:', args=={(s,r) for t,r,s in alternate})
print('Gold event-role assignments:', sorted(gold))
print('Spurious assignments from Algorithm 1:', sorted(decoded-gold))
PY"
